mapper.select:
SELECT id, user_id, goal_id, task_id, study_date, duration_minutes, content,
       reflection, focus_score, created_at, updated_at
FROM study_record
WHERE user_id = #{userId}
AND study_date >= #{startDate}
AND study_date <= #{endDate}
ORDER BY study_date DESC, created_at DESC

SELECT id, user_id, goal_id, task_id, study_date, duration_minutes, content,
       reflection, focus_score, created_at, updated_at
FROM study_record WHERE id = #{id}
